import json
p=json.load(open('p2.json'))
names=['XL','mp','mq','kiv','kpv','TPf','TVf','TQf','TE']
params={n:float(v) for n,v in zip(names,p)}
sub={
 "params":params,
 "defs":{
   "Vcmd":"Vset+mq*(Q0-Qm)",
   "E":"kpv*(Vcmd-Vm)+xv",
   "P":"V*Ef*sin(dl-theta)/XL",
   "Q":"V*(Ef*cos(dl-theta)-V)/XL"
 },
 "states":{
   "Pm":{"rhs":"(P-Pm)/TPf","init":"P0"},
   "Qm":{"rhs":"(Q-Qm)/TQf","init":"Q0"},
   "Vm":{"rhs":"(V-Vm)/TVf","init":"V0"},
   "dl":{"rhs":"2*pi*60*mp*(P0-Pm)","init":"theta0+atan2(P0*XL/V0,V0+Q0*XL/V0)"},
   "xv":{"rhs":"kiv*(Vcmd-Vm)","init":"sqrt((V0+Q0*XL/V0)**2+(P0*XL/V0)**2)"},
   "Ef":{"rhs":"(E-Ef)/TE","init":"sqrt((V0+Q0*XL/V0)**2+(P0*XL/V0)**2)"}
 },
 "outputs":{"P":"P","Q":"Q"}
}
json.dump(sub,open('submission.json','w'),indent=1)
print(open('submission.json').read()[:300])

